[CmdletBinding()]
param([string]$Destination='C:\agente\config\mysql-tls-lab-20261025',[string]$CaDirectory='C:\agente\config\mysql-ca-lab-20261025')
$ErrorActionPreference='Stop'
foreach($path in @($Destination,$CaDirectory)){if(Test-Path -LiteralPath $path){throw 'No sobrescribir material TLS'};$acl=[Security.AccessControl.DirectorySecurity]::new();$acl.SetAccessRuleProtection($true,$false);foreach($sid in @([Security.Principal.WindowsIdentity]::GetCurrent().User,[Security.Principal.SecurityIdentifier]::new('S-1-5-18'),[Security.Principal.SecurityIdentifier]::new('S-1-5-32-544'))){$acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new($sid,'FullControl','ContainerInherit,ObjectInherit','None','Allow'))};if($path -eq $Destination){$acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new([Security.Principal.SecurityIdentifier]::new('S-1-5-20'),'ReadAndExecute','ContainerInherit,ObjectInherit','None','Allow'))};[IO.FileSystemAclExtensions]::CreateDirectory($acl,$path)|Out-Null}
$caKey=[Security.Cryptography.RSA]::Create(3072);$req=[Security.Cryptography.X509Certificates.CertificateRequest]::new('CN=Nexbyte MySQL LAB CA 20261025',$caKey,[Security.Cryptography.HashAlgorithmName]::SHA256,[Security.Cryptography.RSASignaturePadding]::Pkcs1)
$req.CertificateExtensions.Add([Security.Cryptography.X509Certificates.X509BasicConstraintsExtension]::new($true,$false,0,$true));$req.CertificateExtensions.Add([Security.Cryptography.X509Certificates.X509KeyUsageExtension]::new([Security.Cryptography.X509Certificates.X509KeyUsageFlags]::KeyCertSign -bor [Security.Cryptography.X509Certificates.X509KeyUsageFlags]::CrlSign,$true))
$ca=$req.CreateSelfSigned([DateTimeOffset]::UtcNow.AddMinutes(-5),[DateTimeOffset]::UtcNow.AddYears(2))
$key=[Security.Cryptography.RSA]::Create(3072);$req=[Security.Cryptography.X509Certificates.CertificateRequest]::new('CN=localhost',$key,[Security.Cryptography.HashAlgorithmName]::SHA256,[Security.Cryptography.RSASignaturePadding]::Pkcs1)
$san=[Security.Cryptography.X509Certificates.SubjectAlternativeNameBuilder]::new();$san.AddDnsName('localhost');$san.AddIpAddress([Net.IPAddress]::Parse('127.0.0.1'));$req.CertificateExtensions.Add($san.Build())
$req.CertificateExtensions.Add([Security.Cryptography.X509Certificates.X509BasicConstraintsExtension]::new($false,$false,0,$true));$req.CertificateExtensions.Add([Security.Cryptography.X509Certificates.X509KeyUsageExtension]::new([Security.Cryptography.X509Certificates.X509KeyUsageFlags]::DigitalSignature -bor [Security.Cryptography.X509Certificates.X509KeyUsageFlags]::KeyEncipherment,$true))
$oid=[Security.Cryptography.OidCollection]::new();[void]$oid.Add([Security.Cryptography.Oid]::new('1.3.6.1.5.5.7.3.1'));$req.CertificateExtensions.Add([Security.Cryptography.X509Certificates.X509EnhancedKeyUsageExtension]::new($oid,$true))
$serial=[Security.Cryptography.RandomNumberGenerator]::GetBytes(16);$cert=$req.Create($ca,[DateTimeOffset]::UtcNow.AddMinutes(-5),[DateTimeOffset]::UtcNow.AddDays(365),$serial)
$chain=[Security.Cryptography.X509Certificates.X509Chain]::new();$chain.ChainPolicy.TrustMode='CustomRootTrust';$chain.ChainPolicy.CustomTrustStore.Add($ca);$chain.ChainPolicy.RevocationMode='NoCheck';if(-not $chain.Build($cert)){throw 'Cadena local no verificada'}
[IO.File]::WriteAllText((Join-Path $CaDirectory 'ca-key.pem'),$caKey.ExportPkcs8PrivateKeyPem());[IO.File]::WriteAllText((Join-Path $Destination 'ca.pem'),$ca.ExportCertificatePem());[IO.File]::WriteAllBytes((Join-Path $Destination 'ca.cer'),$ca.Export('Cert'));[IO.File]::WriteAllText((Join-Path $Destination 'server-cert.pem'),$cert.ExportCertificatePem());[IO.File]::WriteAllText((Join-Path $Destination 'server-key.pem'),$key.ExportPkcs8PrivateKeyPem())
$files=Get-ChildItem -LiteralPath $Destination -File|ForEach-Object {@{archivo=$_.Name;sha256=(Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash}}
@{estado='CA_Y_SERVIDOR_VERIFICADOS';san=@('localhost','127.0.0.1');vigenteHasta=$cert.NotAfter.ToUniversalTime().ToString('o');archivos=$files}|ConvertTo-Json -Depth 4|Set-Content -LiteralPath (Join-Path $Destination 'manifest.json')
$caKey.Dispose();$key.Dispose();$ca.Dispose();$cert.Dispose()
Write-Output 'TLS_LAB_GENERADO: cadena local verificada, sin confianza global'
